_recstore_original_generate_initial_values = (
    RecStoreBackend._generate_initial_values
)


def _recstore_batch_generate_initial_values(self, num_rows):
    if (
        _os.environ.get("QUANTA_RECSTORE_BATCH_INIT", "0") != "1"
        or num_rows <= 0
        or "TruncNormalInitializer" not in str(self.initializer)
    ):
        return _recstore_original_generate_initial_values(self, num_rows)

    block_rows = int(self.block_size)
    generated_rows = ((int(num_rows) + block_rows - 1) // block_rows) * block_rows
    values = torch.empty(
        (int(num_rows), self.embedding_dim),
        dtype=torch.float32,
        device="cpu",
    )
    block = self.initializer.generate(
        [generated_rows, self.embedding_dim]
    ).detach().to(device="cpu", dtype=torch.float32).reshape(
        -1, self.embedding_dim
    )
    values.copy_(block[:num_rows])
    return values


RecStoreBackend._generate_initial_values = _recstore_batch_generate_initial_values


_recstore_original_lookup_unlocked = RecStoreBackend._lookup_unlocked


def _recstore_lookup_unlocked_with_empty_init_result(
    self,
    ids,
    hashtable,
    readonly=False,
    assume_unique=False,
    return_cpu_ids=False,
):
    direct_empty_init = (
        self.owns_storage
        and not readonly
        and ids.numel() > 0
        and self._engine_empty
        and self._direct_bulk_init_available
    )
    try:
        result = _recstore_original_lookup_unlocked(
            self,
            ids,
            hashtable,
            readonly=readonly,
            assume_unique=assume_unique,
            return_cpu_ids=return_cpu_ids,
        )
    except TypeError:
        if (
            not direct_empty_init
            or self._engine_empty
            or self._direct_bulk_init_available
        ):
            raise
        return _recstore_original_lookup_unlocked(
            self,
            ids,
            hashtable,
            readonly=readonly,
            assume_unique=assume_unique,
            return_cpu_ids=return_cpu_ids,
        )
    if result is not None or not direct_empty_init or self._engine_empty:
        return result
    return _recstore_original_lookup_unlocked(
        self,
        ids,
        hashtable,
        readonly=readonly,
        assume_unique=assume_unique,
        return_cpu_ids=return_cpu_ids,
    )


RecStoreBackend._lookup_unlocked = _recstore_lookup_unlocked_with_empty_init_result


def _recstore_value_output_buffer(self, num_rows, pin_output):
    if _os.environ.get("QUANTA_RECSTORE_OUTPUT_CACHE", "1") == "0":
        return torch.empty(
            (num_rows, self.embedding_dim),
            dtype=torch.float32,
            device="cpu",
            pin_memory=pin_output,
        )
    cache = getattr(self, "_value_output_buffer_cache", None)
    if cache is None:
        cache = {}
        self._value_output_buffer_cache = cache
    key = (num_rows, pin_output, self.embedding_dim)
    values = cache.get(key)
    if values is None:
        values = torch.empty(
            (num_rows, self.embedding_dim),
            dtype=torch.float32,
            device="cpu",
            pin_memory=pin_output,
        )
        cache[key] = values
    return values


def _recstore_missing_positions_buffer(self, num_rows):
    positions = getattr(self, "_missing_positions_buffer", None)
    if positions is None or positions.numel() < num_rows:
        positions = torch.empty(num_rows, dtype=torch.int64, device="cpu")
        self._missing_positions_buffer = positions
    return positions


def _recstore_update_value_lookup_stats(
    self,
    num_rows,
    missing_rows,
    unique_missing_rows,
    repaired_rows,
    legacy_fallback,
):
    stats = getattr(self, "_value_lookup_stats", None)
    if stats is None:
        stats = {
            "calls": 0,
            "rows": 0,
            "miss_batches": 0,
            "missing_rows": 0,
            "unique_missing_rows": 0,
            "repaired_rows": 0,
            "avoided_hit_rechecks": 0,
            "legacy_fallback_batches": 0,
            "legacy_reprocessed_rows": 0,
        }
        self._value_lookup_stats = stats
    stats["calls"] += 1
    stats["rows"] += int(num_rows)
    stats["missing_rows"] += int(missing_rows)
    stats["unique_missing_rows"] += int(unique_missing_rows)
    stats["repaired_rows"] += int(repaired_rows)
    if missing_rows:
        stats["miss_batches"] += 1
    if repaired_rows:
        stats["avoided_hit_rechecks"] += int(num_rows - missing_rows)
    if legacy_fallback:
        stats["legacy_fallback_batches"] += 1
        stats["legacy_reprocessed_rows"] += int(num_rows)


def _recstore_value_lookup_stats(self):
    stats = getattr(self, "_value_lookup_stats", {})
    result = dict(stats)
    calls = int(result.get("calls", 0))
    rows = int(result.get("rows", 0))
    result["miss_batch_rate"] = (
        float(result.get("miss_batches", 0)) / calls if calls else 0.0
    )
    result["missing_row_rate"] = (
        float(result.get("missing_rows", 0)) / rows if rows else 0.0
    )
    return result


def _recstore_lookup_values(
    self,
    ids,
    hashtable,
    readonly=False,
    assume_unique=False,
):
    with self._table_lock:
        if not hasattr(self.engine, "lookup_values_into_raw"):
            _, values, ids_cpu = self._lookup_unlocked(
                ids,
                hashtable,
                readonly=readonly,
                assume_unique=assume_unique,
                return_cpu_ids=True,
            )
            return values, ids_cpu

        total_start = time.perf_counter()
        ids_cpu = self._lookup_ids_cpu(ids, retain=True)
        ids_cpu_end = time.perf_counter()
        num_rows = ids_cpu.numel()
        pin_output = (
            self._use_pinned_outputs and ids.device.type == "cuda"
        )
        values = _recstore_value_output_buffer(self, num_rows, pin_output)
        output_alloc_end = time.perf_counter()
        partial_repair = (
            _os.environ.get("QUANTA_RECSTORE_PARTIAL_MISS_REPAIR", "1") != "0"
            and hasattr(self.engine, "lookup_values_with_misses_into_raw")
        )
        missing_positions = (
            _recstore_missing_positions_buffer(self, num_rows)
            if partial_repair
            else None
        )
        if self._profile_lookup:
            engine_profile = dict(
                self.engine.lookup_values_with_misses_into_raw_profiled(
                    ids_cpu.data_ptr(), num_rows, values.data_ptr(),
                    missing_positions.data_ptr(), True,
                ) if partial_repair else
                self.engine.lookup_values_into_raw_profiled(
                    ids_cpu.data_ptr(), num_rows, values.data_ptr(), True,
                )
            )
            missing_rows = int(engine_profile["missing_rows"])
        else:
            engine_profile = None
            missing_rows = int(
                self.engine.lookup_values_with_misses_into_raw(
                    ids_cpu.data_ptr(), num_rows, values.data_ptr(),
                    missing_positions.data_ptr(), True,
                ) if partial_repair else
                self.engine.lookup_values_into_raw(
                    ids_cpu.data_ptr(), num_rows, values.data_ptr(), True,
                )
            )
        engine_end = time.perf_counter()

        if missing_rows != 0:
            if not partial_repair:
                _, fallback_values, fallback_ids = self._lookup_unlocked(
                    ids_cpu,
                    hashtable,
                    readonly=readonly,
                    assume_unique=assume_unique,
                    return_cpu_ids=True,
                )
                fallback_end = time.perf_counter()
                _recstore_update_value_lookup_stats(
                    self, num_rows, missing_rows, 0, 0, True
                )
                if self._profile_lookup:
                    fallback_profile = self.last_lookup_profile
                    self.last_lookup_profile = {
                        "lookup_path": "value_only_legacy_fallback",
                        "value_only_rows": int(num_rows),
                        "missing_rows": int(missing_rows),
                        "miss_batch": 1,
                        "miss_repair_rows": 0,
                        "avoided_hit_rechecks": 0,
                        "ids_d2h_us": (ids_cpu_end - total_start) * 1_000_000.0,
                        "output_alloc_us": (
                            output_alloc_end - ids_cpu_end
                        ) * 1_000_000.0,
                        "engine_wall_us": (
                            engine_end - output_alloc_end
                        ) * 1_000_000.0,
                        "legacy_fallback_us": (
                            fallback_end - engine_end
                        ) * 1_000_000.0,
                        "lookup_total_us": (
                            fallback_end - total_start
                        ) * 1_000_000.0,
                        "fallback_profile": fallback_profile,
                    }
                return fallback_values, fallback_ids

            repair_start = time.perf_counter()
            positions = missing_positions[:missing_rows]
            missing_ids = ids_cpu.index_select(0, positions)
            unique_missing_rows = (
                missing_rows
                if assume_unique
                else int(torch.unique(missing_ids).numel())
            )
            select_end = time.perf_counter()
            _, repair_values, _ = self._lookup_unlocked(
                missing_ids,
                hashtable,
                readonly=readonly,
                assume_unique=assume_unique,
                return_cpu_ids=True,
            )
            repair_lookup_end = time.perf_counter()
            values.index_copy_(0, positions, repair_values)
            repair_end = time.perf_counter()
            repair_profile = self.last_lookup_profile
            _recstore_update_value_lookup_stats(
                self,
                num_rows,
                missing_rows,
                unique_missing_rows,
                missing_rows,
                False,
            )
        else:
            repair_start = engine_end
            select_end = engine_end
            repair_lookup_end = engine_end
            repair_end = engine_end
            repair_profile = None
            unique_missing_rows = 0
            _recstore_update_value_lookup_stats(self, num_rows, 0, 0, 0, False)

        if self._profile_lookup:
            self.last_lookup_profile = {
                "lookup_path": (
                    "value_only_partial_repair"
                    if missing_rows else "value_only_hit"
                ),
                "value_only_rows": int(num_rows),
                "missing_rows": int(missing_rows),
                "unique_missing_rows": int(unique_missing_rows),
                "miss_batch": int(missing_rows != 0),
                "miss_repair_rows": int(missing_rows),
                "avoided_hit_rechecks": int(
                    num_rows - missing_rows if missing_rows else 0
                ),
                "ids_d2h_us": (ids_cpu_end - total_start) * 1_000_000.0,
                "ids_numpy_us": 0.0,
                "output_alloc_us": (
                    output_alloc_end - ids_cpu_end
                ) * 1_000_000.0,
                "engine_wall_us": (
                    engine_end - output_alloc_end
                ) * 1_000_000.0,
                "engine_internal_us": float(
                    engine_profile["total_ns"]
                ) / 1000.0,
                "engine_get_us": float(
                    engine_profile["engine_get_unpack_ns"]
                ) / 1000.0,
                "engine_index_max_us": float(
                    engine_profile["engine_index_lookup_max_ns"]
                ) / 1000.0,
                "engine_copy_us": float(
                    engine_profile["row_copy_max_ns"]
                ) / 1000.0,
                "engine_unpack_us": 0.0,
                "output_wrap_us": 0.0,
                "missing_positions_compact_us": float(
                    engine_profile.get("missing_positions_compact_ns", 0.0)
                ) / 1000.0,
                "missing_scan_us": (
                    select_end - repair_start
                ) * 1_000_000.0,
                "missing_dedup_us": 0.0,
                "missing_init_us": (
                    repair_lookup_end - select_end
                ) * 1_000_000.0,
                "missing_scatter_us": (
                    repair_end - repair_lookup_end
                ) * 1_000_000.0,
                "missing_put_us": 0.0,
                "miss_init_put_us": (
                    repair_lookup_end - select_end
                ) * 1_000_000.0,
                "miss_repair_us": (
                    repair_end - repair_start
                ) * 1_000_000.0,
                "repair_profile": repair_profile,
                "lookup_total_us": (
                    repair_end - total_start
                ) * 1_000_000.0,
            }
        return values, ids_cpu


RecStoreBackend.lookup_values = _recstore_lookup_values
RecStoreBackend.value_lookup_stats = _recstore_value_lookup_stats
